UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'Leather arm greaves made by elves. Because the magnificent workmanship, the arm greaves are very light and flexible.' THEN 'Leather arm greaves are a sensible addition to any suit of armor. Made of hardened leather, the arm greaves are held in place by laces and buckles.' ELSE "LocaText" END WHERE "LocaId" = 'infoid_arme_elfenschienen_01';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'These close-fitting leggings are ideal for moving through undergrowth at speed as well as for combat maneuvers. Apparently a spell causes extreme pain on those who wear them, so that only Elves can wear them safely.' THEN 'Tight buckskin pants. These close-fitting pants are ideal for moving through undergrowth at speed.' ELSE "LocaText" END WHERE "LocaId" = 'infoid_hose_waldlaeufer';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'These thin leather boots of bleached buckskin are decorated with elven runes and patterns. The elven magical runes have turned these boots as light as a feather, therefore the wearer will have his reflexes enhanced during combat. Apparently a spell causes extreme pain on those who wear them, so that only Elves can wear them safely.' THEN 'These thin leather boots of bleached buckskin are decorated with elven runes and patterns.' ELSE "LocaText" END WHERE "LocaId" = 'infoid_schuhe_lederstiefel_06';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'A disgusting herbal brew invented by amateur alchemist Tradan Brewmore in his capacity as innkeeper of the Silver Pitcher. This brew tastes so awful, it makes you want to throw up. Nevertheless, it is good for you and can sober up even the drunkest of Dwarves. Whether this makes it worth drinking remains a matter of debate.\n\nEffect: ED +15\nDuration: immediate\n' THEN 'A disgusting herbal brew invented by amateur alchemist Tradan Brewmore in his capacity as innkeeper of the Silver Pitcher. This brew tastes so awful, it makes you want to throw up. Nevertheless, it is good for you and can sober up even the drunkest of Dwarves. Whether this makes it worth drinking remains a matter of debate.\n\nEffect: ED +5' ELSE "LocaText" END WHERE "LocaId" = 'infoid_special_dunklesspecial';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'Hair pins are useful tools when you need to pick a lock or two. Unfortunately, they usually get so twisted in the process that they can only be used once. It''s always worth having a couple on you.\n\nEffect: TA Pick Locks +2' THEN 'Hair pins are useful tools when you need to pick a lock or two. Unfortunately, they usually get so twisted in the process that they can only be used once. It''s always worth having a couple on you.\n\nEffect: TA Pick Locks +1' ELSE "LocaText" END WHERE "LocaId" = 'infoid_special_haarnadel';
